const openAlertWithPrefix = `-- name: OpenAlertWithPrefix :one
SELECT id, created_at, updated_at, kind, severity, message, is_resolved, resolved_at, hub_id, acknowledged_at, acknowledged_by_id, delivery_channel, resolve_note, resolved_by_id, status FROM operations_alert
WHERE hub_id IS NOT DISTINCT FROM $1::uuid AND kind = $2
  AND status IN ('OPEN', 'ACKNOWLEDGED', 'ESCALATED') AND starts_with(message, $3::text)
ORDER BY created_at DESC LIMIT 1
`

type OpenAlertWithPrefixParams struct {
	Hub    *uuid.UUID
	Kind   string
	Prefix string
}

// _open_alert dedupe: same hub + kind, still live, message starting with the prefix.
func (q *Queries) OpenAlertWithPrefix(ctx context.Context, arg OpenAlertWithPrefixParams) (OperationsAlert, error) {
	row := q.db.QueryRow(ctx, openAlertWithPrefix, arg.Hub, arg.Kind, arg.Prefix)
	var i OperationsAlert
	err := row.Scan(
		&i.ID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Kind,
		&i.Severity,
		&i.Message,
		&i.IsResolved,
		&i.ResolvedAt,
		&i.HubID,
		&i.AcknowledgedAt,
		&i.AcknowledgedByID,
		&i.DeliveryChannel,
		&i.ResolveNote,
		&i.ResolvedByID,
		&i.Status,
	)
	return i, err
}

